 '<div class="t83-savebar"><button class="t83-btn light" data-profile-back>← STUDENT LIST</button>'+(canEdit?'<button class="t83-btn blue" data-profile-save>SAVE</button><button class="t83-btn green" data-profile-next>SAVE & NEXT INCOMPLETE →</button>':'')+'</div>';
 $$('[data-formtab]',container).forEach(b=>b.onclick=()=>{$$('[data-formtab]',container).forEach(x=>x.classList.toggle('active',x===b));$$('.t83-form-section',container).forEach(x=>x.classList.toggle('active',x.dataset.section===b.dataset.formtab))});
 $('[data-profile-back]',container).onclick=()=>renderIdentList(mount,ctx,directory,null);
 const dob=$('[name="date_of_birth"]',container),age=$('[name="age_auto"]',container);const setAge=()=>{if(!age)return;const v=dob&&dob.value;if(!v){age.value='';return}const d=new Date(v+'T00:00:00'),n=new Date();let a=n.getFullYear()-d.getFullYear();if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--;age.value=a>=0?a:''};if(dob){dob.onchange=setAge;setAge()}
