function attendanceSummary(rows){let total=rows.length,boys=0,girls=0,present=0,absent=0;rows.forEach(r=>{const sex=norm(r.sex),s=norm(r._status||r.attendance_status||'PRESENT');if(sex==='M'||sex==='MALE')boys++;if(sex==='F'||sex==='FEMALE')girls++;if(s==='PRESENT'||s==='LATE'||s==='SCHOOL_ACTIVITY'||s==='SPORT')present++;else absent++});return{total,boys,girls,present,absent,percent:total?100*present/total:0}}
function attKpis(s){return '<div class="t83-att-summary">'+[['TOTAL',s.total],['BOYS',s.boys],['GIRLS',s.girls],['PRESENT',s.present],['ABSENT',s.absent],['% PRESENT',s.percent.toFixed(1)+'%']].map(x=>'<div class="t83-mini-kpi"><b>'+esc(x[1])+'</b><span>'+x[0]+'</span></div>').join('')+'</div>'}
const ATT_STATUS=['PRESENT','ABSENT','LATE','EXCUSED','SICK','PERMISSION'];
function attRowsHtml(rows){return rows.map((r,i)=>{const s=norm(r.attendance_status||'PRESENT');return '<tr data-att-row="'+esc(r.student_id)+'"><td class="center">'+(i+1)+'</td><td>'+esc(r.sdms_code)+'</td><td class="name">'+esc(r.student_name)+'</td><td class="center">'+esc(r.sex)+'</td><td><select class="t83-status-select" data-att-status>'+ATT_STATUS.map(x=>'<option '+(s===x?'selected':'')+'>'+x+'</option>').join('')+'</select></td><td><input class="t83-reason" data-att-reason value="'+esc(r.reason||'')+'" placeholder="Reason if exception"></td></tr>'}).join('')}
function attMobileHtml(rows){return rows.map(r=>{const s=norm(r.attendance_status||'PRESENT');return '<div class="t83-mobile-card" data-att-row="'+esc(r.student_id)+'"><div class="top"><b>'+esc(r.student_name)+'</b><small>'+esc(r.sex)+' · '+esc(r.sdms_code)+'</small></div><div class="t83-form-grid two"><div class="t83-field"><label>Status</label><select data-att-status>'+ATT_STATUS.map(x=>'<option '+(s===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="t83-field"><label>Reason</label><input data-att-reason value="'+esc(r.reason||'')+'" placeholder="Reason if needed"></div></div></div>'}).join('')}
function syncAttendanceViews(root,source){const row=source.closest('[data-att-row]'),id=row&&row.dataset.attRow;if(!id)return;const status=$('[data-att-status]',row).value,reason=$('[data-att-reason]',row).value;$$('[data-att-row="'+CSS.escape(id)+'"]',root).forEach(x=>{const s=$('[data-att-status]',x),r=$('[data-att-reason]',x);if(s&&s!==source)s.value=status;if(r&&r!==source)r.value=reason});updateAttSummary(root)}
function collectAttendance(root,base,includeFollow=false){return (base||[]).map(r=>{const row=$('[data-att-row="'+CSS.escape(String(r.student_id))+'"]',root),s=row?$('[data-att-status]',row).value:'PRESENT',reason=row?$('[data-att-reason]',row).value:'';return{student_id:r.student_id,attendance_status:s,arrival_time:null,reason:reason||null,teacher_advice:null,...(includeFollow?{follow_up_required:false}:{})}})}
function validateAttendance(rows){const exceptions=new Set(['ABSENT','LATE','EXCUSED','SICK','PERMISSION']);const bad=rows.find(r=>exceptions.has(r.attendance_status)&&!r.reason);return bad?'Reason is required for every absence, late, excused, sick or permission status.':''}
function wireAttendanceRows(root,base){$$('[data-att-status],[data-att-reason]',root).forEach(e=>e.addEventListener(e.tagName==='SELECT'?'change':'input',()=>syncAttendanceViews(root,e)));const all=$('[data-mark-all-present]',root);if(all)all.onclick=()=>{$$('[data-att-status]',root).forEach(s=>s.value='PRESENT');$$('[data-att-reason]',root).forEach(r=>r.value='');updateAttSummary(root)};root.__t83_att_base=base;updateAttSummary(root)}
function updateAttSummary(root){const base=root.__t83_att_base||[],rows=collectAttendance(root,base);const box=$('[data-att-summary]',root);if(box)box.innerHTML=attKpis(attendanceSummary(rows.map((x,i)=>Object.assign({},base[i],{_status:x.attendance_status}))))}

