function saveSubjectAttendance(mount,d,btn,submit){const body=$('[data-sa-body]',mount),rows=collectAttendance(body,d.rows||[],false),err=validateAttendance(rows);if(err)return flash(mount,err,'warn');const c=ctxIds(),x=d.context||{},l=d.__lesson||{},done=busy(btn,submit?'SUBMITTING…':'SAVING…');rpc('save_subject_attendance',{p_academic_year_id:c.ayId,p_term_id:c.termId,p_class_id:x.class_id||l.class_id,p_subject_id:x.subject_id||l.subject_id,p_lesson_date:x.lesson_date,p_rows:rows,p_period_id:x.period_id||l.period_id,p_submit:submit,p_notes:null}).then(()=>{flash(mount,submit?'Subject attendance submitted successfully.':'Subject attendance draft saved.','success');return rpc('r174_teacher_subject_attendance_entry',{p_class_id:x.class_id||l.class_id,p_subject_id:x.subject_id||l.subject_id,p_lesson_date:x.lesson_date,p_period_id:x.period_id||l.period_id})}).then(z=>{z.__lesson=l;renderSubjectAttendanceEntry(mount,LAST_CTX,z)}).catch(e=>flash(mount,'Attendance save failed: '+errorText(e),'error')).finally(done)}

