V.teacherMarks83=function(mount,ctx){
 page(mount,ctx,true);mount.innerHTML=serviceHead('Marks & Assessments','Formula authority: server-side CAMIS / Exam / Final % / Grade / Rank')+'<div class="t83-formula-note">FORMULA SAFETY: This screen does not recalculate CAMIS, exam contribution, final percentage, grade or rank in the browser. It displays the authoritative values returned by Supabase.</div><div class="t83-toolbar"><div class="t83-field t83-search"><label>Class · Subject</label><select data-ma-assign><option value="">SELECT CLASS / SUBJECT</option></select></div><div class="t83-field"><label>&nbsp;</label><button class="t83-btn blue" data-ma-open>OPEN WORKSPACE</button></div></div><div data-ma-body></div>';wireBack(mount,ctx);getFast().then(d=>{const sel=$('[data-ma-assign]',mount),a=d.assignments||[];sel.innerHTML='<option value="">SELECT CLASS / SUBJECT</option>'+a.map((x,i)=>'<option value="'+i+'">'+esc(x.class_code+' · '+x.subject_name)+'</option>').join('');sel.__assign=a}).catch(e=>flash(mount,errorText(e),'error'));$('[data-ma-open]',mount).onclick=()=>openMarksWorkspace(mount,ctx)};
function openMarksWorkspace(mount,ctx){const sel=$('[data-ma-assign]',mount),btn=$('[data-ma-open]',mount);if(!sel||sel.value==='')return flash(mount,'Select a class and subject first.','warn');const i=Number(sel.value),a=sel.__assign&&sel.__assign[i];if(!a)return flash(mount,'Select a class and subject first.','warn');const done=busy(btn,'OPENING…');rpc('r174_teacher_marks_workspace',{p_class_id:a.class_id,p_subject_id:a.subject_id}).then(d=>{d.__assignment=a;renderMarksWorkspace(mount,ctx,d)}).catch(e=>flash(mount,errorText(e),'error')).finally(done)}
function renderMarksWorkspace(mount,ctx,d){const body=$('[data-ma-body]',mount),ass=d.assessments||[],cats=d.categories||[],a=d.__assignment||{};body.innerHTML=panel(a.class_code+' · '+a.subject_name,num(d.student_count)+' students · CAMIS max '+val(d.camis_max,''),'<div class="t83-toolbar" style="grid-template-columns:minmax(130px,1fr) 90px auto"><div class="t83-field"><label>Assessment Type</label><select data-new-cat><option value="">SELECT TYPE</option>'+cats.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="t83-field"><label>Max Mark</label><input type="number" min="1" data-new-max></div><div class="t83-field"><label>&nbsp;</label><button class="t83-btn green" data-new-assessment>CREATE / OPEN</button></div></div><div class="t83-table-wrap"><table class="t83-table"><thead><tr><th>ASSESSMENT</th><th style="width:12%">MAX</th><th style="width:14%">DATE</th><th style="width:14%">STATUS</th><th style="width:14%">PROGRESS</th><th style="width:12%">ACTION</th></tr></thead><tbody>'+(ass.length?ass.map(x=>'<tr><td class="name">'+esc(x.assessment_name)+'</td><td class="center">'+esc(x.max_mark)+'</td><td class="center">'+esc(x.assessment_date||'—')+'</td><td class="center">'+esc(x.workflow_status||x.status||'DRAFT')+'</td><td class="center">'+num(x.completed_or_status_rows)+' / '+num(d.student_count)+'</td><td class="center"><button class="t83-btn blue small" data-open-ass="'+esc(x.assessment_id)+'">OPEN</button></td></tr>').join(''):'<tr><td colspan="6">'+empty('No assessment yet. Create one above.')+'</td></tr>')+'</tbody></table></div>')+'<div data-ma-entry></div>';const nb=$('[data-new-assessment]',body);nb.onclick=()=>{const cat=$('[data-new-cat]',body).value,max=Number($('[data-new-max]',body).value);if(!cat||!max||max<=0)return flash(mount,'Select assessment type and enter a valid maximum mark.','warn');const done=busy(nb,'CREATING…');rpc('r174_teacher_open_assessment',{p_class_id:a.class_id,p_subject_id:a.subject_id,p_category_id:cat,p_max_mark:max}).then(x=>{x.__assignment=a;renderMarksEntry(mount,x)}).catch(e=>flash(mount,errorText(e),'error')).finally(done)};$$('[data-open-ass]',body).forEach(b=>b.onclick=()=>{const done=busy(b,'OPENING…');rpc('r174_teacher_marks_entry_data',{p_class_id:a.class_id,p_subject_id:a.subject_id,p_assessment_id:b.dataset.openAss}).then(x=>{x.__assignment=a;renderMarksEntry(mount,x)}).catch(e=>flash(mount,errorText(e),'error')).finally(done)})}
function fnum(v){return v==null||v===''?'—':Number(v).toFixed(Number(v)%1?1:0)}
function formulaPair(v,m){return v==null?'—':fnum(v)+(m!=null?' / '+fnum(m):'')}
function renderMarksEntry(mount,d){const entry=$('[data-ma-entry]',mount),rows=d.rows||[],as=d.assessment||{},a=d.__assignment||{},editable=as.editable!==false;entry.innerHTML=panel('MARK ENTRY · '+val(as.assessment_name,''),'Maximum '+val(as.max_mark,'')+' · '+val(as.workflow_status,'DRAFT'),'<div class="t83-formula-note">Calculated columns are READ ONLY and come from the server formula engine.</div><div class="t83-table-wrap t83-desktop-only"><table class="t83-table t83-marks-table"><thead><tr><th>NO</th><th>SDMS</th><th>STUDENT</th><th>CURRENT ASSESSMENT</th><th>ASS. TOTAL</th><th>CAMIS E.U</th><th>CAMIS EXAM</th><th>TOTAL CAMIS</th><th>FINAL %</th><th>GRADE</th><th>RANK</th></tr></thead><tbody>'+rows.map((r,i)=>marksRow(r,i,editable)).join('')+'</tbody></table></div><div class="t83-mobile-list">'+rows.map((r,i)=>marksMobile(r,i,editable)).join('')+'</div>'+(editable?'<div class="t83-savebar"><button class="t83-btn blue" data-marks-save>SAVE DRAFT</button><button class="t83-btn green" data-marks-submit>SUBMIT MARKS</button></div>':'<div class="t83-flash show info">This assessment is not editable in its current workflow status.</div>'));wireMarkInputs(entry,rows);if(editable){$('[data-marks-save]',entry).onclick=e=>saveMarks(mount,d,e.currentTarget,false);$('[data-marks-submit]',entry).onclick=e=>saveMarks(mount,d,e.currentTarget,true)}}
function marksRow(r,i,editable){const status=norm(r.entry_status||(r.entry_mark!=null?'MARK':'N'));return '<tr data-mark-row="'+esc(r.student_id)+'"><td class="center">'+(i+1)+'</td><td>'+esc(r.sdms_code)+'</td><td class="name">'+esc(r.student_name)+'</td><td><div class="t83-mark-entry"><input type="number" step="0.01" min="0" max="'+esc(r.current_max||'')+'" data-mark-value value="'+esc(r.entry_mark==null?'':r.entry_mark)+'" '+(!editable||status!=='MARK'?'disabled':'')+'><select data-mark-status '+(!editable?'disabled':'')+'>'+['MARK','A','E','S','N','P'].map(x=>'<option '+(status===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div></td><td class="center t83-formula">'+esc(formulaPair(r.all_ass_obtained,r.all_ass_max))+'</td><td class="center t83-formula">'+esc(formulaPair(r.camis_eu,r.camis_max))+'</td><td class="center t83-formula">'+esc(formulaPair(r.camis_exam,r.camis_exam_max))+'</td><td class="center t83-formula">'+esc(formulaPair(r.total_marks,r.total_marks_max))+'</td><td class="center t83-formula">'+esc(pct(r.percentage))+'</td><td class="center t83-formula">'+esc(val(r.grade,''))+'</td><td class="center t83-formula">'+esc(val(r.rank,''))+'</td></tr>'}
function marksMobile(r,i,editable){const status=norm(r.entry_status||(r.entry_mark!=null?'MARK':'N'));return '<div class="t83-mobile-card" data-mark-row="'+esc(r.student_id)+'"><div class="top"><b>'+(i+1)+'. '+esc(r.student_name)+'</b><small>'+esc(r.sdms_code)+'</small></div><div class="t83-form-grid two"><div class="t83-field"><label>Mark</label><input type="number" step="0.01" min="0" max="'+esc(r.current_max||'')+'" data-mark-value value="'+esc(r.entry_mark==null?'':r.entry_mark)+'" '+(!editable||status!=='MARK'?'disabled':'')+'></div><div class="t83-field"><label>Status</label><select data-mark-status '+(!editable?'disabled':'')+'>'+['MARK','A','E','S','N','P'].map(x=>'<option '+(status===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div></div><div class="meta"><b>ASS:</b> '+esc(formulaPair(r.all_ass_obtained,r.all_ass_max))+' · <b>CAMIS:</b> '+esc(formulaPair(r.camis_eu,r.camis_max))+' · <b>EXAM:</b> '+esc(formulaPair(r.camis_exam,r.camis_exam_max))+' · <b>FINAL:</b> '+esc(pct(r.percentage))+' · <b>'+esc(val(r.grade,''))+'</b> · Rank '+esc(val(r.rank,''))+'</div></div>'}
function wireMarkInputs(root,rows){const initial=new Map(rows.map(r=>[String(r.student_id),{mark:r.entry_mark==null?'':String(r.entry_mark),status:norm(r.entry_status||(r.entry_mark!=null?'MARK':'N'))}]));root.__markInitial=initial;$$('[data-mark-status]',root).forEach(s=>s.onchange=()=>{const row=s.closest('[data-mark-row]'),id=row.dataset.markRow,status=s.value;$$('[data-mark-row="'+CSS.escape(id)+'"]',root).forEach(x=>{const ss=$('[data-mark-status]',x),inp=$('[data-mark-value]',x);if(ss!==s)ss.value=status;if(status!=='MARK'){inp.value='';inp.disabled=true}else inp.disabled=false})});$$('[data-mark-value]',root).forEach(inp=>inp.oninput=()=>{const row=inp.closest('[data-mark-row]'),id=row.dataset.markRow;$$('[data-mark-row="'+CSS.escape(id)+'"]',root).forEach(x=>{const ii=$('[data-mark-value]',x),ss=$('[data-mark-status]',x);if(ii!==inp)ii.value=inp.value;if(inp.value!==''){ss.value='MARK';ii.disabled=false}})})}
function collectMarks(root,submit){const map=new Map();$$('[data-mark-row]',root).forEach(row=>{const id=row.dataset.markRow;if(map.has(id))return;const status=$('[data-mark-status]',row).value,inp=$('[data-mark-value]',row),mark=inp&&inp.value!==''?Number(inp.value):null;map.set(id,{student_id:id,mark:status==='MARK'?mark:null,mark_status:status,remarks:null})});const all=Array.from(map.values()),init=root.__markInitial||new Map();if(submit){const bad=all.find(x=>(x.mark_status==='MARK'&&x.mark==null)||['N','P'].includes(x.mark_status));if(bad)throw new Error('Complete every student with a numeric mark or A / E / S before Submit.')}return all.filter(x=>{const z=init.get(String(x.student_id))||{mark:'',status:'N'};return String(x.mark==null?'':x.mark)!==String(z.mark)||x.mark_status!==z.status})}
function saveMarks(mount,d,btn,submit){const entry=$('[data-ma-entry]',mount);let rows;try{rows=collectMarks(entry,submit)}catch(e){return flash(mount,errorText(e),'warn')}const as=d.assessment||{},done=busy(btn,submit?'SUBMITTING…':'SAVING…');rpc('r174_teacher_save_marks',{p_assessment_id:as.id,p_rows:rows,p_submit:submit}).then(x=>{x.__assignment=d.__assignment;flash(mount,submit?'Marks submitted successfully.':'Marks draft saved successfully.','success');renderMarksEntry(mount,x)}).catch(e=>flash(mount,'Marks save failed: '+errorText(e),'error')).finally(done)}

