V.teacherPerformance83=function(mount,ctx){
 page(mount,ctx,true);mount.innerHTML=serviceHead('Student Performance','Select one class/subject. Final results use server-calculated percentages.')+'<div class="t83-toolbar"><div class="t83-field t83-search"><label>Class · Subject</label><select data-perf-assign><option value="">SELECT CLASS / SUBJECT</option></select></div><div class="t83-field"><label>&nbsp;</label><button class="t83-btn blue" data-perf-load>SHOW PERFORMANCE</button></div></div><div data-perf-body></div>';wireBack(mount,ctx);getFast().then(d=>{const sel=$('[data-perf-assign]',mount),a=d.assignments||[];sel.innerHTML='<option value="">SELECT CLASS / SUBJECT</option>'+a.map((x,i)=>'<option value="'+i+'">'+esc(x.class_code+' · '+x.subject_name)+'</option>').join('');sel.__assign=a}).catch(e=>flash(mount,errorText(e),'error'));$('[data-perf-load]',mount).onclick=()=>{const sel=$('[data-perf-assign]',mount),btn=$('[data-perf-load]',mount);if(!sel||sel.value==='')return flash(mount,'Select a class and subject first.','warn');const a=sel.__assign&&sel.__assign[Number(sel.value)];if(!a)return flash(mount,'Select a class and subject first.','warn');const done=busy(btn,'ANALYSING…');rpc('r174_teacher_marks_entry_data',{p_class_id:a.class_id,p_subject_id:a.subject_id,p_assessment_id:null}).then(d=>renderPerformance(mount,a,d)).catch(e=>flash(mount,errorText(e),'error')).finally(done)}};
function renderPerformance(mount,a,d){const rows=(d.rows||[]).filter(r=>r.percentage!=null),avg=rows.length?rows.reduce((s,r)=>s+num(r.percentage),0)/rows.length:0,passed=rows.filter(r=>num(r.percentage)>=50).length,failed=rows.filter(r=>num(r.percentage)<50).length,sorted=rows.slice().sort((x,y)=>num(y.percentage)-num(x.percentage));$('[data-perf-body]',mount).innerHTML='<div class="t83-kpis">'+kpi(rows.length,'RESULTS','blue')+kpi(avg.toFixed(1)+'%','AVERAGE','navy')+kpi(passed,'PASSED ≥50%','green')+kpi(failed,'FAILED <50%','red')+'</div>'+panel(a.class_code+' · '+a.subject_name,'Highest '+(sorted[0]?sorted[0].student_name+' '+pct(sorted[0].percentage):'—')+' · Lowest '+(sorted.length?sorted[sorted.length-1].student_name+' '+pct(sorted[sorted.length-1].percentage):'—'),'<div class="t83-table-wrap t83-desktop-only"><table class="t83-table"><thead><tr><th style="width:7%">RANK</th><th>STUDENT</th><th style="width:16%">TOTAL CAMIS</th><th style="width:12%">FINAL %</th><th style="width:10%">GRADE</th><th style="width:13%">STATUS</th></tr></thead><tbody>'+sorted.map(r=>'<tr><td class="center">'+esc(val(r.rank,''))+'</td><td class="name">'+esc(r.student_name)+'</td><td class="center">'+esc(formulaPair(r.total_marks,r.total_marks_max))+'</td><td class="center"><b>'+esc(pct(r.percentage))+'</b></td><td class="center">'+esc(val(r.grade,''))+'</td><td class="center"><span class="t83-pill '+(num(r.percentage)>=50?'complete':'notstarted')+'">'+(num(r.percentage)>=50?'PASS':'FAIL')+'</span></td></tr>').join('')+'</tbody></table></div><div class="t83-mobile-list">'+sorted.map(r=>'<div class="t83-mobile-card"><div class="top"><b>#'+esc(val(r.rank,''))+' '+esc(r.student_name)+'</b><span class="t83-pill '+(num(r.percentage)>=50?'complete':'notstarted')+'">'+(num(r.percentage)>=50?'PASS':'FAIL')+'</span></div><div class="meta">Final '+esc(pct(r.percentage))+' · Grade '+esc(val(r.grade,''))+' · Total '+esc(formulaPair(r.total_marks,r.total_marks_max))+'</div></div>').join('')+'</div>')}

/* ========================= REPORTS ========================= */
V.teacherReports83=function(mount,ctx){
 page(mount,ctx,true);const c=ctxIds();mount.innerHTML=serviceHead('Teacher Reports','Only teacher-owned reports in the live report catalog','<button class="t83-btn blue small" data-t83-print>PRINT</button>')+'<div data-report-body><div class="t83-skeleton"></div></div>';wireBack(mount,ctx);$('[data-t83-print]',mount).onclick=()=>window.print();rpc('r166_teacher_reports',{p_academic_year_id:c.ayId,p_term_id:c.termId}).then(d=>{const cat=d.catalog||[],sub=d.submissions||[];$('[data-report-body]',mount).innerHTML='<div class="t83-kpis">'+kpi(cat.length,'REPORT TYPES','blue')+kpi(sub.length,'SUBMISSIONS','green')+kpi(sub.filter(x=>norm(x.submission_status)==='PENDING').length,'PENDING','gold')+kpi(sub.filter(x=>norm(x.submission_status)==='SUBMITTED').length,'SUBMITTED','navy')+'</div>'+panel('AVAILABLE REPORTS','Print/download remains enabled by the backend','<div class="t83-table-wrap"><table class="t83-table"><thead><tr><th>REPORT</th><th style="width:18%">GROUP</th><th style="width:18%">PERIODS</th><th style="width:12%">PAPER</th></tr></thead><tbody>'+cat.map(r=>'<tr><td class="name">'+esc(r.report_name)+'<br><small>'+esc(r.description||'')+'</small></td><td>'+esc(r.service_group||'')+'</td><td>'+esc([r.supports_daily&&'DAILY',r.supports_weekly&&'WEEKLY',r.supports_monthly&&'MONTHLY',r.supports_termly&&'TERMLY'].filter(Boolean).join(' · '))+'</td><td class="center">'+esc((r.paper_size||'A4')+' '+(r.orientation||''))+'</td></tr>').join('')+'</tbody></table></div>')+(sub.length?panel('REPORT SUBMISSIONS','Current term','<div class="t83-table-wrap"><table class="t83-table"><thead><tr><th>REPORT</th><th>PERIOD</th><th>DUE</th><th>STATUS</th></tr></thead><tbody>'+sub.map(x=>'<tr><td>'+esc(x.report_name)+'</td><td>'+esc(x.reporting_period||'')+'</td><td>'+esc(x.due_date||'—')+'</td><td>'+esc(x.submission_status||'—')+'</td></tr>').join('')+'</tbody></table></div>'):'')}).catch(e=>{$('[data-report-body]',mount).innerHTML=empty(errorText(e))})};

