V.teacherAccount83=function(mount,ctx){
 page(mount,ctx,true);LAST_CTX=ctx;const p=window.BOOT&&BOOT.profile||{},c=ctxIds();
 mount.innerHTML=serviceHead('Account','Teacher profile and password security')+
 '<div class="t83-grid2">'+
 panel('MY PROFILE','Authenticated staff account','<div class="t83-list"><div class="t83-list-row"><div><b>FULL NAME</b><span>'+esc(p.full_name||'')+'</span></div></div><div class="t83-list-row"><div><b>STAFF CODE</b><span>'+esc(p.staff_code||'')+'</span></div></div><div class="t83-list-row"><div><b>EMAIL</b><span>'+esc(p.email||'')+'</span></div></div><div class="t83-list-row"><div><b>PHONE</b><span>'+esc(p.phone||'')+'</span></div></div><div class="t83-list-row"><div><b>ROLE / CONTEXT</b><span>TEACHER · '+esc(c.ay)+' · '+esc(c.term)+'</span></div></div></div>')+
 panel('CHANGE PASSWORD','Updates your real Supabase login password','<div class="t83-form-grid two"><div class="t83-field"><label>New Password</label><input type="password" data-ac-new autocomplete="new-password" placeholder="At least 8 characters"></div><div class="t83-field"><label>Confirm New Password</label><input type="password" data-ac-confirm autocomplete="new-password" placeholder="Repeat new password"></div></div><div class="t83-actions" style="justify-content:flex-start;margin-top:6px"><button class="t83-btn blue" data-ac-save>UPDATE PASSWORD</button></div>')+
 '</div>';wireBack(mount,ctx);
 const b=$('[data-ac-save]',mount);b.onclick=async()=>{const a=$('[data-ac-new]',mount).value,z=$('[data-ac-confirm]',mount).value;if(a.length<8)return flash(mount,'Use at least 8 characters for the new password.','warn');if(a!==z)return flash(mount,'The two passwords do not match.','warn');const ss=L&&typeof L.session==='function'?L.session():null;if(!ss||!ss.access_token)return flash(mount,'Your login session is missing. Sign in again.','error');const done=busy(b,'UPDATING…');try{const res=await fetch('https://xydrwpbgikwsxerqwkik.supabase.co/auth/v1/user',{method:'PUT',cache:'no-store',headers:{apikey:'sb_publishable_-k49Hut2E8SNIJLvofL4JQ_jW1K865r',Authorization:'Bearer '+ss.access_token,'Content-Type':'application/json'},body:JSON.stringify({password:a})});const tx=await res.text();let data={};try{data=tx?JSON.parse(tx):{}}catch(_){}if(!res.ok)throw new Error(data.message||data.error_description||data.error||('HTTP '+res.status));$('[data-ac-new]',mount).value='';$('[data-ac-confirm]',mount).value='';flash(mount,'Password updated successfully. Your username / staff code did not change.','success')}catch(e){flash(mount,'Password update failed: '+errorText(e),'error')}finally{done()}}
};

